mapper.select:
SELECT n.id, n.title, n.type, n.level, n.target_type, n.publish_status, u.nickname AS publisher_name, n.publish_time, n.revoke_time, n.create_time FROM sys_notice n LEFT JOIN sys_user u ON u.id = n.publisher_id AND u.is_deleted = 0 WHERE n.is_deleted = 0
AND n.title LIKE CONCAT('%', #{queryParams.title}, '%')
AND n.publish_status = #{queryParams.publishStatus}
AND n.publish_time >= #{startDate}
AND n.publish_time <= #{endDate}
ORDER BY n.publish_time DESC, n.create_time DESC
